mod monitor {
    pub struct Capability<T>(std::marker::PhantomData<T>);   // field private: unforgeable
    pub struct Vault { store: Store, policy: Policy }        // private to this module
    impl Vault {
        pub fn check(&self, subject: &Subject) -> Option<Capability<Read>> {
            let principal = subject.principal()?;            // absent identity: no capability
            self.policy.allows(principal, Action::Read).then(|| Capability(std::marker::PhantomData))
        }
        pub fn read(&self, _proof: Capability<Read>, id: Id) -> Record { self.store.get(id) }
    }
}
